        if (ord.riderId !== riderId) throw new Error("\u0986\u09AA\u09A8\u09BF \u098F\u0987 \u0985\u09B0\u09CD\u09A1\u09BE\u09B0\u09C7 \u09A8\u09BF\u09DF\u09CB\u099C\u09BF\u09A4 \u09B0\u09BE\u0987\u09A1\u09BE\u09B0 \u09A8\u09A8\u0964");
